// newBagMappings is the ADDITIVE, conflict-safe retro applied to EXISTING v11-log-* indices on
// upgrade. It only adds the ip .keyword sub-field (the coordinate-map fix) + the event/controls bags. It
// never retypes an existing leaf (a base-type change 400s and needs a reindex), so old indices fully
// converge to the canonical logIndexMappings template on their next reindex/roll-off.

const newBagMappings = `{"origin":{"properties":{"ip":{"type":"ip","fields":{"keyword":{"type":"keyword","ignore_above":256}}}}},"target":{"properties":{"ip":{"type":"ip","fields":{"keyword":{"type":"keyword","ignore_above":256}}}}},"event":{"type":"flat_object"},"controls":{"type":"keyword"}}`

